package catalog

import (
	"context"
	"time"

	"github.com/tanvoxyz/tanvo/libs/core"
)

// TaxFilter narrows [TaxRepository.List].
type TaxFilter struct {
	// AutoGenerated, when set, keeps only taxes whose AutoGenerated flag
	// equals it.
	AutoGenerated *bool
	// AppliedToOrganization, when set, keeps only the taxes that are (true)
	// or are not (false) taxes of the organization's default billing
	// entity.
	AppliedToOrganization *bool
	// Search keeps taxes whose name or code contains the trimmed term
	// (case-insensitive, with LIKE wildcards matched literally).
	Search string
	// Order is the list order; core.OrderRecent lists by name (byte
	// order), then by creation instant, newest first, then by ID ascending
	// (lago TaxesQuery).
	Order core.ListOrder
}

// TaxRepository stores taxes. Every method is scoped to an organization.
// Taxes are soft-deleted (lago tax.rb discard on deleted_at): a discarded
// one keeps its row with DeletedAt set, Get still returns it, and every
// other read sees kept rows only.
type TaxRepository interface {
	// Create inserts t; a code already used by a kept tax of the
	// organization fails with core.ErrConflict.
	Create(ctx context.Context, t *Tax) error
	// Update replaces the stored kept tax t.ID with t (same uniqueness
	// rule).
	Update(ctx context.Context, t *Tax) error
	// Discard soft-deletes the kept tax id at at and detaches it from
	// every owner (billing entities, customers, plans, charges, fixed
	// charges, add-ons and commitments); issued documents keep their
	// applied-tax snapshots (domain §7.7, lago Taxes::DestroyService). A
	// missing or discarded tax fails with core.ErrNotFound; its code is
	// free again.
	Discard(ctx context.Context, org core.OrganizationID, id core.TaxID, at time.Time) error
	// Get returns the tax id, kept or discarded, or core.ErrNotFound;
	// callers serving kept taxes check DeletedAt.
	Get(ctx context.Context, org core.OrganizationID, id core.TaxID) (*Tax, error)
	// GetByCode returns the kept tax with that code, or core.ErrNotFound.
	// It also finds the auto-generated EU taxes by their codes (domain
	// §22.10).
	GetByCode(ctx context.Context, org core.OrganizationID, code string) (*Tax, error)
	// ListByCodes returns the kept taxes with the given codes, in the
	// order of codes; a missing code fails with core.ErrNotFound.
	ListByCodes(ctx context.Context, org core.OrganizationID, codes []string) ([]*Tax, error)
	// ListByIDs returns the kept taxes with the given IDs, in the order of
	// ids; a missing ID fails with core.ErrNotFound.
	ListByIDs(ctx context.Context, org core.OrganizationID, ids []core.TaxID) ([]*Tax, error)
	// List returns the organization's kept taxes matching f in the order
	// f.Order; an undeclared order fails with core.ErrInvalidValue.
	List(ctx context.Context, org core.OrganizationID, f TaxFilter, page core.PageRequest) (core.Page[*Tax], error)
}

// CommitmentRepository stores plan commitments. Every method is scoped to
// an organization.
type CommitmentRepository interface {
	// Create inserts c; a second commitment of the same type on the plan
	// fails with core.ErrConflict.
	Create(ctx context.Context, c *Commitment) error
	// Update replaces the stored commitment c.ID with c.
	Update(ctx context.Context, c *Commitment) error
	// Delete removes the commitment id.
	Delete(ctx context.Context, org core.OrganizationID, id core.CommitmentID) error
	// Get returns the commitment id, or core.ErrNotFound.
	Get(ctx context.Context, org core.OrganizationID, id core.CommitmentID) (*Commitment, error)
	// GetByPlan returns the plan's commitment of type t, or
	// core.ErrNotFound.
	GetByPlan(ctx context.Context, org core.OrganizationID, plan core.PlanID, t CommitmentType) (*Commitment, error)
	// ListByPlan returns the plan's commitments in creation order.
	ListByPlan(ctx context.Context, org core.OrganizationID, plan core.PlanID) ([]*Commitment, error)
}

// UsageThresholdRepository stores the usage thresholds of plans and
// subscriptions. Every method is scoped to an organization. Thresholds are
// soft-deleted (lago usage_threshold.rb discard on deleted_at): a
// discarded one keeps its row with DeletedAt set for the invoices that
// reached it, Get still returns it, and every other read sees kept rows
// only.
type UsageThresholdRepository interface {
	// Create inserts u; a second kept recurring threshold, or a
	// non-recurring amount already used by a kept threshold, for the same
	// owner fails with core.ErrConflict.
	Create(ctx context.Context, u *UsageThreshold) error
	// Update replaces the stored kept threshold u.ID with u (same rules).
	Update(ctx context.Context, u *UsageThreshold) error
	// Discard soft-deletes the kept threshold id at at; a missing or
	// discarded one fails with core.ErrNotFound.
	Discard(ctx context.Context, org core.OrganizationID, id core.UsageThresholdID, at time.Time) error
	// Get returns the threshold id, kept or discarded, or
	// core.ErrNotFound.
	Get(ctx context.Context, org core.OrganizationID, id core.UsageThresholdID) (*UsageThreshold, error)
	// ListByPlan returns the plan's kept thresholds by ascending amount,
	// the recurring one last.
	ListByPlan(ctx context.Context, org core.OrganizationID, plan core.PlanID) ([]*UsageThreshold, error)
	// ListBySubscription returns the subscription's own kept thresholds by
	// ascending amount, the recurring one last.
	ListBySubscription(ctx context.Context, org core.OrganizationID, sub core.SubscriptionID) ([]*UsageThreshold, error)
}

// FeatureListFilter selects the features FeatureRepository.List returns.
type FeatureListFilter struct {
	// Search keeps features whose name, code or description contains the
	// trimmed term (case-insensitive, with LIKE wildcards matched
	// literally; lago Entitlement::FeaturesQuery).
	Search string
	// Order is the list order; core.OrderRecent lists by creation instant,
	// newest first, then by ID ascending (lago base_query.rb:111-112).
	Order core.ListOrder
}

// FeatureRepository stores features with their privileges, as one
// aggregate. Every method is scoped to an organization. Features and
// privileges are soft-deleted: a discarded one keeps its row with DeletedAt
// set and is invisible to every other method, and its code can be used
// again (lago app/models/entitlement/feature.rb:5-9, privilege.rb:5-9).
type FeatureRepository interface {
	// Create inserts f and its privileges; a code used by a kept feature of
	// the organization, or a privilege code repeated in the feature, fails
	// with core.ErrConflict.
	Create(ctx context.Context, f *Feature) error
	// Update replaces the kept feature f.ID with f. Privileges are matched
	// by code: a kept privilege whose code is in f is updated in place and
	// keeps its ID (written back into f), a new code is inserted, and a
	// kept privilege whose code is missing from f is discarded at
	// f.UpdatedAt together with its values in the feature's kept
	// entitlements (lago feature_update_service.rb:66-111).
	Update(ctx context.Context, f *Feature) error
	// Discard soft-deletes the kept feature id and its kept privileges at
	// at (lago feature.privileges.discard_all! and feature.discard!,
	// feature_destroy_service.rb:25-26); a missing or discarded one fails
	// with core.ErrNotFound. Its entitlements are discarded separately,
	// with EntitlementRepository.DiscardByFeature in the same transaction;
	// its subscription removals are left as they are.
	Discard(ctx context.Context, org core.OrganizationID, id core.FeatureID, at time.Time) error
	// Get returns the kept feature id with its kept privileges, or
	// core.ErrNotFound.
	Get(ctx context.Context, org core.OrganizationID, id core.FeatureID) (*Feature, error)
	// GetByCode returns the kept feature with that code, or
	// core.ErrNotFound.
	GetByCode(ctx context.Context, org core.OrganizationID, code string) (*Feature, error)
	// ListByIDs returns the kept features with the given IDs, in the order
	// of ids; a missing or discarded ID fails with core.ErrNotFound.
	ListByIDs(ctx context.Context, org core.OrganizationID, ids []core.FeatureID) ([]*Feature, error)
	// List returns the organization's kept features matching f, in the
	// order f.Order; an invalid order fails with core.ErrInvalidValue.
	List(ctx context.Context, org core.OrganizationID, f FeatureListFilter, page core.PageRequest) (core.Page[*Feature], error)
}

// EntitlementRepository stores the entitlements of plans and subscriptions
// and the subscriptions' removals. Every method is scoped to an
// organization. Entitlements are soft-deleted: a discarded one keeps its
// row with DeletedAt set and is invisible to every other method (lago
// app/models/entitlement/entitlement.rb:5-9).
type EntitlementRepository interface {
	// Create inserts e; a second kept entitlement of the same feature for
	// the same owner fails with core.ErrConflict.
	Create(ctx context.Context, e *Entitlement) error
	// Update replaces the stored kept entitlement e.ID with e.
	Update(ctx context.Context, e *Entitlement) error
	// Discard soft-deletes the kept entitlement id at at, with its values
	// (lago entitlement.discard!); a missing or discarded one fails with
	// core.ErrNotFound.
	Discard(ctx context.Context, org core.OrganizationID, id core.EntitlementID, at time.Time) error
	// DiscardByFeature soft-deletes every kept entitlement of the feature
	// at at and returns how many (lago feature.entitlements.discard_all!,
	// feature_destroy_service.rb:24).
	DiscardByFeature(ctx context.Context, org core.OrganizationID, feature core.FeatureID, at time.Time) (int, error)
	// Get returns the kept entitlement id, or core.ErrNotFound.
	Get(ctx context.Context, org core.OrganizationID, id core.EntitlementID) (*Entitlement, error)
	// ListByPlan returns the plan's kept entitlements in creation order.
	ListByPlan(ctx context.Context, org core.OrganizationID, plan core.PlanID) ([]*Entitlement, error)
	// ListBySubscription returns the subscription's own kept entitlements
	// in creation order.
	ListBySubscription(ctx context.Context, org core.OrganizationID, sub core.SubscriptionID) ([]*Entitlement, error)
	// ListByFeature returns the feature's kept entitlements, of plans and
	// of subscriptions, in creation order (lago feature.entitlements).
	ListByFeature(ctx context.Context, org core.OrganizationID, feature core.FeatureID) ([]*Entitlement, error)
	// CreateRemoval inserts r; the same removal twice fails with
	// core.ErrConflict.
	CreateRemoval(ctx context.Context, r *EntitlementRemoval) error
	// DeleteRemoval removes the removal id.
	DeleteRemoval(ctx context.Context, org core.OrganizationID, id core.EntitlementRemovalID) error
	// ListRemovalsBySubscription returns the subscription's removals in
	// creation order.
	ListRemovalsBySubscription(ctx context.Context, org core.OrganizationID, sub core.SubscriptionID) ([]*EntitlementRemoval, error)
}
